//! Tests for the v1.0 APM trace decoder.
//!
//! The primary test decodes a golden payload generated by the reference Go encoder
//! (`pkg/proto/pbgo/trace/idx`) using its inline string-streaming `MarshalMsg`, which is the
//! encoding real tracers emit. The remaining tests exercise individual primitives and error paths
//! with small hand-built MessagePack inputs.

use base64::{engine::general_purpose, Engine as _};
use proptest::prelude::*;
use rmp::encode;
use saluki_common::collections::FastHashMap;
use saluki_core::data_model::event::trace::AttributeValue;
use stringtheory::MetaString;

use super::error::DecodeError;
use super::string_table::StringTable;
use super::{decode_span, decode_v1_payload, read, split_trace_id, value};

/// Golden payload produced by the reference Go encoder.
///
/// Covers: payload metadata (fields 2-9), payload-level attributes, two chunks, all seven
/// `AnyValue` types, span links, span events, 128-bit trace IDs, and string deduplication.
const GOLDEN_PAYLOAD_B64: &str = "";

fn ms(s: &str) -> MetaString {
    MetaString::from(s)
}

/// Looks up an attribute by string key, panicking if absent.
fn attr<'a>(m: &'a FastHashMap<MetaString, AttributeValue>, k: &str) -> &'a AttributeValue {
    m.get(&ms(k)).unwrap_or_else(|| panic!("missing attribute {k}"))
}

#[test]
fn golden_full_payload() {
    let bytes = general_purpose::STANDARD
        .decode(GOLDEN_PAYLOAD_B64)
        .expect("golden payload is valid base64");
    let traces = decode_v1_payload(&bytes).expect("golden payload should decode");
    assert_eq!(traces.len(), 2, "expected two chunks -> two traces");

    // --- First (rich) trace ---
    let t0 = &traces[0];
    assert_eq!(t0.trace_id_high, 0x0001_0203_0405_0607);
    assert_eq!(t0.trace_id_low, 0x0809_0a0b_0c0d_0e0f);
    assert_eq!(t0.origin.as_ref(), "lambda");
    assert_eq!(t0.priority, Some(2));
    assert_eq!(t0.sampling_mechanism, 4);
    assert!(!t0.dropped_trace);

    // Payload-level metadata is cloned onto every trace.
    assert_eq!(t0.payload.container_id.as_ref(), "container-1");
    assert_eq!(t0.payload.language_name.as_ref(), "go");
    assert_eq!(t0.payload.language_version.as_ref(), "1.24");
    assert_eq!(t0.payload.tracer_version.as_ref(), "v2.1.0");
    assert_eq!(t0.payload.runtime_id.as_ref(), "rt-uuid");
    assert_eq!(t0.payload.env.as_ref(), "prod");
    assert_eq!(t0.payload.hostname.as_ref(), "host-a");
    assert_eq!(t0.payload.app_version.as_ref(), "9.9.9");

    // Attribute merge: chunk overrides payload on `pkey`; payload `common` and chunk `ckey` survive.
    assert_eq!(attr(&t0.attributes, "pkey"), &AttributeValue::String(ms("chunkval")));
    assert_eq!(
        attr(&t0.attributes, "common"),
        &AttributeValue::String(ms("common-val"))
    );
    assert_eq!(attr(&t0.attributes, "ckey"), &AttributeValue::String(ms("cval")));

    assert_eq!(t0.spans().len(), 1);
    let s = &t0.spans()[0];
    assert_eq!(s.service(), "svc-a");
    assert_eq!(s.name(), "op-a");
    assert_eq!(s.resource(), "GET /a");
    assert_eq!(s.span_type(), "web");
    assert_eq!(s.span_id(), 111);
    assert_eq!(s.parent_id(), 0);
    assert_eq!(s.start(), 1000);
    assert_eq!(s.duration(), 500);
    assert_eq!(s.error(), 1);
    assert_eq!(s.env.as_ref(), "prod");
    assert_eq!(s.version.as_ref(), "9.9.9");
    assert_eq!(s.component.as_ref(), "net/http");
    assert_eq!(s.kind, 2);

    // All seven AnyValue types.
    assert_eq!(attr(&s.attributes, "str_attr"), &AttributeValue::String(ms("hello")));
    assert_eq!(attr(&s.attributes, "bool_attr"), &AttributeValue::Bool(true));
    assert_eq!(attr(&s.attributes, "dbl_attr"), &AttributeValue::Float(2.5));
    assert_eq!(attr(&s.attributes, "int_attr"), &AttributeValue::Int(42));
    assert_eq!(
        attr(&s.attributes, "bytes_attr"),
        &AttributeValue::Bytes(vec![0xDE, 0xAD, 0xBE, 0xEF])
    );
    assert_eq!(
        attr(&s.attributes, "arr_attr"),
        &AttributeValue::Array(vec![AttributeValue::Int(1), AttributeValue::String(ms("two"))])
    );
    assert_eq!(
        attr(&s.attributes, "kvl_attr"),
        &AttributeValue::KeyValueList(vec![(ms("nested"), AttributeValue::Int(7))])
    );

    // Span link.
    assert_eq!(s.span_links().len(), 1);
    let link = &s.span_links()[0];
    assert_eq!(link.trace_id_high(), 0x1011_1213_1415_1617);
    assert_eq!(link.trace_id(), 0x1819_1a1b_1c1d_1e1f);
    assert_eq!(link.span_id(), 222);
    assert_eq!(link.tracestate(), "ts=1");
    assert_eq!(link.flags(), 0x8000_0001);
    assert_eq!(attr(link.attributes(), "lk"), &AttributeValue::String(ms("lv")));

    // Span event.
    assert_eq!(s.span_events().len(), 1);
    let event = &s.span_events()[0];
    assert_eq!(event.time_unix_nano(), 1500);
    assert_eq!(event.name(), "evt");
    assert_eq!(attr(event.attributes(), "ek"), &AttributeValue::String(ms("ev")));

    // --- Second (minimal) trace ---
    // The reference encoder omits default-valued fields, so a chunk with priority 0 and an empty
    // origin transmits neither field: priority decodes to `None`, origin to the empty string.
    let t1 = &traces[1];
    assert_eq!(t1.priority, None);
    assert_eq!(t1.origin.as_ref(), "");
    assert!(t1.dropped_trace);
    assert_eq!(t1.spans().len(), 1);
    assert_eq!(t1.spans()[0].service(), "svc-a");
    assert_eq!(t1.spans()[0].name(), "op-b");
    assert_eq!(t1.spans()[0].span_id(), 333);
}

#[test]
fn streaming_string_literal_then_reference() {
    // A literal string is added to the table; a later uint32 index resolves to the same value.
    let mut strings = StringTable::new();

    let mut buf = Vec::new();
    encode::write_str(&mut buf, "abc").unwrap();
    let mut r = buf.as_slice();
    let v = value::read_streaming_string(&mut r, &mut strings, "test").unwrap();
    assert_eq!(v.as_ref(), "abc");
    assert_eq!(strings.len(), 2, "literal should have been added to the table");

    let mut buf = Vec::new();
    encode::write_uint(&mut buf, 1).unwrap();
    let mut r = buf.as_slice();
    let v = value::read_streaming_string(&mut r, &mut strings, "test").unwrap();
    assert_eq!(
        v.as_ref(),
        "abc",
        "index 1 should resolve to the previously added string"
    );
}

#[test]
fn streaming_string_unseen_index_rejected() {
    let mut strings = StringTable::new();
    let mut buf = Vec::new();
    encode::write_uint(&mut buf, 5).unwrap();
    let mut r = buf.as_slice();
    let err = value::read_streaming_string(&mut r, &mut strings, "test").unwrap_err();
    assert!(matches!(err, DecodeError::UnseenStringIndex { index: 5, .. }));
}

